INSERT INTO _pdd_proposal SELECT * FROM jsonb_to_recordset($pdd_data$[{"from_pdd":1,"to_pdd":96,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Ambas entradas expresan recuperación tras una dificultad; resiliencia es la capacidad y alzar la cabeza es recuperar el ánimo o la dignidad.","connection_type":"Directa"},{"from_pdd":1,"to_pdd":239,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Las dos definiciones se refieren a recursos personales que aparecen ante la adversidad; la cita destaca la fuerza y resiliencia añade recuperación.","connection_type":"Directa"},{"from_pdd":2,"to_pdd":395,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Verbalizar convierte ideas en palabras; la elocuencia añade claridad y capacidad expresiva a ese mismo acto, sin que sean sinónimos exactos.","connection_type":"Directa"},{"from_pdd":7,"to_pdd":46,"relationship_type":"contraste_de_uso","strength":3,"explanation_es":"Dar por sentado acepta algo como seguro sin cuestionarlo; epojé consiste precisamente en suspender ese juicio para observar antes de concluir.","connection_type":"Contraste"},{"from_pdd":7,"to_pdd":309,"relationship_type":"contraste_de_uso","strength":3,"explanation_es":"La pregunta exige razones para una certeza que dar por sentado acepta sin examinarlas; permite contrastar dos actitudes ante la misma afirmación.","connection_type":"Contraste"},{"from_pdd":9,"to_pdd":165,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Dominguero, en la definición del proyecto, es un excursionista ocasional y poco experimentado: comparte la práctica no profesional de aficionado, con un matiz específico y a veces despectivo.","connection_type":"Directa"},{"from_pdd":10,"to_pdd":63,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Ambas entradas describen sensibilidad emocional elevada; susceptible destaca la facilidad para ofenderse, mientras a flor de piel abarca sentimientos intensos de cualquier signo.","connection_type":"Directa"},{"from_pdd":10,"to_pdd":116,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Susceptible reacciona fácilmente a una ofensa y ser de mecha corta pierde pronto la paciencia; coinciden en la reacción fácil, no en todos los tipos de sensibilidad.","connection_type":"Directa"},{"from_pdd":11,"to_pdd":219,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Volver a pasar por el corazón es recordar con emoción; nostalgia es una modalidad de ese recuerdo teñida de tristeza por lo pasado.","connection_type":"Directa"},{"from_pdd":12,"to_pdd":298,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"En la acepción interpersonal, sintonizar es conectar emocionalmente y llevarse a las mil maravillas es entenderse muy bien; se excluye aquí la acepción de ajustar una frecuencia.","connection_type":"Directa"},{"from_pdd":12,"to_pdd":299,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Hacer buenas migas expresa un entendimiento inicial que encaja con sintonizar emocionalmente, aunque la sintonía no exige que la relación sea nueva.","connection_type":"Directa"},{"from_pdd":13,"to_pdd":155,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Dichoso describe a quien siente felicidad; gozar es experimentar o disfrutar un placer que puede producir ese estado, sin equivalencia en la acepción de buena suerte.","connection_type":"Directa"},{"from_pdd":14,"to_pdd":60,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"Paradigma y patrón comparten la acepción de modelo que sirve de referencia; paradigma puede abarcar además un sistema de ideas.","connection_type":"Directa"},{"from_pdd":15,"to_pdd":299,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Entablar una relación es iniciarla; hacer buenas migas precisa que ese inicio trae entendimiento. La relación se limita al comienzo de un vínculo interpersonal.","connection_type":"Directa"},{"from_pdd":16,"to_pdd":71,"relationship_type":"sinonimia","strength":3,"explanation_es":"Serenidad y sosiego designan calma sin agitación; sosiego puede subrayar también la quietud del entorno.","connection_type":"Directa"},{"from_pdd":16,"to_pdd":189,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Recogimiento añade concentración e intimidad reflexiva a la calma interior de serenidad; no son intercambiables en todos los contextos.","connection_type":"Directa"},{"from_pdd":19,"to_pdd":118,"relationship_type":"equivalencia_nominal_verbal","strength":3,"explanation_es":"El elogio es la expresión de reconocimiento que se realiza al halagar sinceramente; halagar puede tener además intención de agradar.","connection_type":"Directa"},{"from_pdd":19,"to_pdd":208,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Echar flores significa dedicar elogios; expresa en locución la misma acción de alabanza que nombra el elogio.","connection_type":"Directa"},{"from_pdd":20,"to_pdd":361,"relationship_type":"acepcion_compartida","strength":3,"explanation_es":"La entrada El prejucio corresponde por su definición a prejuicio, opinión previa sin fundamento; la sala Perjuicio/Prejuicio contrasta esa misma acepción con daño. Se conserva la errata del registro.","connection_type":"Directa"},{"from_pdd":22,"to_pdd":255,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Jactarse es presumir de los propios méritos; sabelotodo caracteriza a quien presume específicamente de saberlo todo. Se contrasta el verbo general con un tipo de presunción.","connection_type":"Directa"},{"from_pdd":23,"to_pdd":89,"relationship_type":"contraste_de_uso","strength":3,"explanation_es":"Hacerse el sueco evita reconocer una responsabilidad; a lo hecho, pecho insta a asumir las consecuencias de lo realizado.","connection_type":"Contraste"},{"from_pdd":23,"to_pdd":103,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Ambas locuciones implican fingir no percibir algo para evitar intervenir: hacerse el sueco simula no entender y hacerse la vista gorda simula no ver.","connection_type":"Directa"},{"from_pdd":23,"to_pdd":268,"relationship_type":"contraste_de_uso","strength":3,"explanation_es":"Dar la cara asume responsabilidad públicamente; hacerse el sueco finge no entender para evitarla. Contrastan respuestas ante una misma exigencia de responsabilidad.","connection_type":"Contraste"},{"from_pdd":24,"to_pdd":29,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"La valentía permite actuar ante el miedo; atrevimiento pone el acento en dar el paso hacia una acción arriesgada.","connection_type":"Directa"},{"from_pdd":24,"to_pdd":54,"relationship_type":"sinonimia","strength":3,"explanation_es":"Atrevimiento y audacia nombran la decisión valiente de emprender algo arriesgado o fuera de lo habitual.","connection_type":"Directa"},{"from_pdd":24,"to_pdd":269,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Tener cara expresa descaro para pedir o actuar; atrevimiento expresa disposición a hacer algo inusual o arriesgado. Se distingue valoración negativa de osadía de un valor que puede ser positivo.","connection_type":"Directa"},{"from_pdd":25,"to_pdd":62,"relationship_type":"contraste_de_significado","strength":3,"explanation_es":"Inquebrantable destaca resistencia que no se vence; vulnerable destaca la facilidad de sufrir daño. Se contrasta resistencia y exposición al daño.","connection_type":"Contraste"},{"from_pdd":25,"to_pdd":167,"relationship_type":"antonimia_parcial","strength":3,"explanation_es":"Precario es inestable e inseguro; inquebrantable es resistente y no cede. Se opone estabilidad frente a fragilidad, no la carencia de recursos en sí misma.","connection_type":"Contraste"},{"from_pdd":26,"to_pdd":242,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Por si las moscas introduce una medida de precaución; precavido describe a quien adopta precisamente esas medidas para evitar riesgos.","connection_type":"Directa"},{"from_pdd":26,"to_pdd":285,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Precavido destaca la anticipación de riesgos; sensatez incluye actuar prudentemente con buen juicio, del que la precaución es una manifestación.","connection_type":"Directa"},{"from_pdd":27,"to_pdd":285,"relationship_type":"sinonimia","strength":3,"explanation_es":"Cordura y sensatez comparten la capacidad de pensar y decidir con buen juicio y prudencia.","connection_type":"Directa"},{"from_pdd":27,"to_pdd":396,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"La cordura supone buen juicio; discernir consiste en distinguir diferencias para comprender y juzgar adecuadamente. Se conecta juicio sensato y discriminación razonada.","connection_type":"Directa"},{"from_pdd":29,"to_pdd":54,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"Audacia es valor para acometer acciones arriesgadas; valentía es afrontar el miedo ante el peligro. Comparten valor, con distinto énfasis en iniciativa y miedo.","connection_type":"Directa"},{"from_pdd":31,"to_pdd":32,"relationship_type":"sinonimia_parcial","strength":2,"explanation_es":"Tremendo y flipante pueden valorar algo como extraordinariamente impresionante; se limita al uso admirativo, no a cualquier intensidad negativa.","connection_type":"Directa"},{"from_pdd":31,"to_pdd":109,"relationship_type":"sinonimia_parcial","strength":2,"explanation_es":"En su acepción de extraordinario o muy grande, tremendo puede aproximarse a grandioso; no se extiende a los usos negativos o temibles de tremendo.","connection_type":"Directa"},{"from_pdd":32,"to_pdd":94,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Algo flipante causa sorpresa o admiración, que es precisamente asombrar; se relaciona la cualidad causante con la acción de causar asombro.","connection_type":"Directa"},{"from_pdd":33,"to_pdd":252,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Fastidiar es molestar o causar contratiempos; un aguafiestas fastidia específicamente la diversión o el entusiasmo ajeno.","connection_type":"Directa"},{"from_pdd":34,"to_pdd":37,"relationship_type":"sinonimia_parcial","strength":2,"explanation_es":"En su acepción de lujo, a todo trapo significa con gran esplendor y se aproxima a fastuoso. No se incluyen los usos de velocidad o intensidad de la locución.","connection_type":"Directa"},{"from_pdd":34,"to_pdd":109,"relationship_type":"sinonimia_parcial","strength":2,"explanation_es":"Fastuoso y grandioso coinciden al valorar algo como magnífico; fastuoso exige lujo y esplendor, que grandioso no siempre implica.","connection_type":"Directa"},{"from_pdd":35,"to_pdd":209,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Una situación pasajera dura poco; como flor de un día expresa esa brevedad, con el matiz frecuente de belleza o intensidad fugaz.","connection_type":"Directa"},{"from_pdd":35,"to_pdd":348,"relationship_type":"antonimia","strength":3,"explanation_es":"Pasajero es de corta duración; interminable parece no acabar. Contrastan directamente dos duraciones.","connection_type":"Contraste"},{"from_pdd":36,"to_pdd":133,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Un aliado es quien apoya y colabora; respaldar es realizar ese apoyo o defensa. Se vincula la función de la persona con la acción correspondiente.","connection_type":"Directa"},{"from_pdd":36,"to_pdd":159,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"Respaldar es apoyar o defender; echar un cable es ayudar. Se aproximan en el apoyo a una persona, aunque ayudar no siempre implique defender una postura.","connection_type":"Directa"},{"from_pdd":36,"to_pdd":391,"relationship_type":"sinonimia_parcial","strength":2,"explanation_es":"Respaldar y sostener pueden significar mantener o apoyar una postura o a una persona. Sostener conserva además el sentido físico de sujetar; respaldar añade defensa o apoyo explícito.","connection_type":"Directa"},{"from_pdd":39,"to_pdd":291,"relationship_type":"sinonimia","strength":3,"explanation_es":"Proeza y hazaña nombran una acción extraordinaria que exige valor, habilidad o gran esfuerzo.","connection_type":"Directa"},{"from_pdd":40,"to_pdd":311,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Vanguardia implica introducir ideas o estilos nuevos; originalidad es crear ideas propias y novedosas. La primera añade una posición innovadora respecto de su época.","connection_type":"Directa"},{"from_pdd":42,"to_pdd":358,"relationship_type":"acepcion_compartida","strength":3,"explanation_es":"Talante corresponde a disposición o actitud personal; la sala Aptitud/Actitud enseña esa misma disposición diferenciándola de la capacidad.","connection_type":"Directa"},{"from_pdd":43,"to_pdd":97,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"Reverdecer expresa recuperación de vitalidad; flores que nunca se detienen es una imagen de vitalidad que se renueva continuamente.","connection_type":"Directa"},{"from_pdd":43,"to_pdd":235,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Necesitar primavera atribuye al mar una renovación; reverdecer expresa volver a adquirir vitalidad. Se compara el sentido figurado de renovarse, no mar y vegetación como objetos.","connection_type":"Directa"},{"from_pdd":43,"to_pdd":272,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Brotar es comenzar a crecer o salir; reverdecer es volver a mostrar verdor o vitalidad. Se contrastan aparición inicial y renovación del crecimiento.","connection_type":"Directa"},{"from_pdd":44,"to_pdd":70,"relationship_type":"contraste_de_uso","strength":3,"explanation_es":"La templanza mantiene el control de una reacción; irse de manos describe que una situación se descontrola o excede los límites.","connection_type":"Contraste"},{"from_pdd":44,"to_pdd":116,"relationship_type":"antonimia_de_actitud","strength":3,"explanation_es":"Templanza es dominio moderado de las emociones; ser de mecha corta es perder fácilmente ese dominio al enfadarse.","connection_type":"Contraste"},{"from_pdd":45,"to_pdd":156,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Persona vitamina y ser la alegría de la huerta caracterizan a alguien cuya presencia anima y aporta bienestar a los demás; la segunda subraya alegría visible.","connection_type":"Directa"},{"from_pdd":46,"to_pdd":108,"relationship_type":"contraste_de_uso","strength":3,"explanation_es":"Epojé suspende la afirmación de certeza; no cabe duda de que declara certeza completa. Son posturas opuestas ante una proposición.","connection_type":"Contraste"},{"from_pdd":46,"to_pdd":215,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"La cita cuestiona la estabilidad de certezas previas cuando cambian las preguntas; epojé suspende juicios para reconsiderar. Se relaciona revisión de la certeza, no mera sorpresa.","connection_type":"Directa"},{"from_pdd":47,"to_pdd":94,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Asombrar causa sorpresa intensa; patidifuso describe a quien queda tan sorprendido que no sabe reaccionar. Se relacionan causa y estado resultante del mismo significado.","connection_type":"Directa"},{"from_pdd":48,"to_pdd":390,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Concatenar es enlazar elementos sucesivos; atar cabos enlaza específicamente pistas o hechos para comprenderlos. No toda concatenación constituye una deducción.","connection_type":"Directa"},{"from_pdd":49,"to_pdd":126,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Saborear es disfrutar atentamente un sabor; saber a gloria califica ese sabor como extraordinariamente agradable. No implican necesariamente comer mucho.","connection_type":"Directa"},{"from_pdd":49,"to_pdd":155,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"Saborear y gozar pueden significar disfrutar una experiencia; saborear añade atención lenta a sus matices y no se limita a tener placer.","connection_type":"Directa"},{"from_pdd":50,"to_pdd":59,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"La convivencia de esta sala se define como relación respetuosa y armónica; concordia nombra precisamente acuerdo y armonía, sin exigir compartir espacio.","connection_type":"Directa"},{"from_pdd":50,"to_pdd":298,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Llevarse a las mil maravillas expresa una relación de gran entendimiento; la convivencia armónica extiende ese entendimiento a quienes comparten espacio.","connection_type":"Directa"},{"from_pdd":52,"to_pdd":87,"relationship_type":"contraste_de_uso","strength":3,"explanation_es":"Demorar supone retrasarse o hacer tardar; darse vidilla pide actuar más deprisa. Contrastan el ritmo de realización de una tarea.","connection_type":"Contraste"},{"from_pdd":52,"to_pdd":294,"relationship_type":"sinonimia","strength":3,"explanation_es":"Demorar y postergar pueden significar retrasar una acción; postergar destaca dejarla deliberadamente para más adelante, mientras demorar también puede ser tardar.","connection_type":"Directa"},{"from_pdd":55,"to_pdd":260,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Un atajo es una ruta que acorta el trayecto; una vereda es un sendero estrecho que puede servir de atajo. Se declara el solapamiento, sin afirmar que toda vereda acorte.","connection_type":"Directa"},{"from_pdd":56,"to_pdd":334,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Garabato es un dibujo rápido y poco cuidado; la cita compara escribir espontáneamente con un boceto, otro trazo preliminar. Comparten el carácter inicial del trazo, no toda obra artística.","connection_type":"Directa"},{"from_pdd":57,"to_pdd":70,"relationship_type":"contraste_de_uso","strength":3,"explanation_es":"Tener la sartén por el mango significa controlar la situación; irse de manos significa perder ese control.","connection_type":"Contraste"},{"from_pdd":57,"to_pdd":323,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"La locución afirma dominio de una situación; la pregunta contrapone dirigir la propia vida a ser arrastrado por ella. El vínculo se limita al contraste explícito de control y pasividad.","connection_type":"Directa"},{"from_pdd":58,"to_pdd":268,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"Encarar es afrontar directamente una dificultad; dar la cara es afrontarla asumiendo responsabilidad o defensa pública.","connection_type":"Directa"},{"from_pdd":58,"to_pdd":310,"relationship_type":"contraste_de_uso","strength":2,"explanation_es":"Encarar afronta una realidad difícil; la relación descrita en la huida se sostiene evitando afrontarla. Se oponen confrontación y evasión en el sentido declarado de la cita.","connection_type":"Contraste"},{"from_pdd":59,"to_pdd":328,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"Tender puentes para llegar a acuerdos es una formulación de la concordia frente a la división; el vínculo es acuerdo explícito, no política en general.","connection_type":"Directa"},{"from_pdd":62,"to_pdd":167,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Vulnerable es susceptible de daño; precario es inseguro o inestable. Coinciden cuando una condición insegura expone a daño, no en todas las acepciones de carencia de recursos.","connection_type":"Directa"},{"from_pdd":64,"to_pdd":136,"relationship_type":"contraste_de_actitud","strength":3,"explanation_es":"Me importa un pimiento declara indiferencia completa; fervor expresa implicación apasionada e intensa hacia algo.","connection_type":"Contraste"},{"from_pdd":64,"to_pdd":146,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Fervor es entusiasmo intenso; enérgica, dentro del par enérgica/energética, describe una actitud de gran energía. Se relaciona la intensidad del ánimo, sin equiparar entusiasmo con una bebida que aporta energía.","connection_type":"Directa"},{"from_pdd":65,"to_pdd":162,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Por arte de birlibirloque atribuye un resultado a magia inexplicable; prodigioso lo valora como casi milagroso. Comparten apariencia extraordinaria, no identidad literal de causa.","connection_type":"Directa"},{"from_pdd":66,"to_pdd":390,"relationship_type":"contraste_de_estado","strength":3,"explanation_es":"Los cabos sueltos son detalles aún sin resolver; atar cabos relaciona esos detalles para que encajen y permitan comprender la situación.","connection_type":"Contraste"},{"from_pdd":67,"to_pdd":303,"relationship_type":"antonimia","strength":3,"explanation_es":"Darse por vencido abandona el intento; persistencia consiste en seguir esforzándose pese a las dificultades.","connection_type":"Contraste"},{"from_pdd":67,"to_pdd":342,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Darse por vencido y tirar la toalla expresan abandonar un esfuerzo al reconocer que no se quiere o no se puede continuar.","connection_type":"Directa"},{"from_pdd":68,"to_pdd":182,"relationship_type":"contraste_de_uso","strength":3,"explanation_es":"Mandar todo a paseo abandona el asunto por frustración; el que la sigue la consigue aconseja perseverar para alcanzar el objetivo.","connection_type":"Contraste"},{"from_pdd":68,"to_pdd":342,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Mandar todo a paseo y tirar la toalla pueden expresar abandono; la primera añade hartazgo o enfado, y la segunda reconocimiento de renuncia.","connection_type":"Directa"},{"from_pdd":69,"to_pdd":158,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Movida puede ser una situación complicada y agitada; liarse parda expresa que se provoca precisamente un gran lío o escándalo.","connection_type":"Directa"},{"from_pdd":69,"to_pdd":184,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"En sentido figurado, movida y torbellino pueden designar una situación de gran agitación; no se relaciona aquí el torbellino de viento.","connection_type":"Directa"},{"from_pdd":70,"to_pdd":273,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Desatar una reacción intensa puede iniciar un descontrol; irse de manos describe ese exceso de control perdido. Se restringe al uso figurado de desatar, no a soltar nudos.","connection_type":"Directa"},{"from_pdd":71,"to_pdd":101,"relationship_type":"antonimia_de_estado","strength":3,"explanation_es":"Sosiego es tranquilidad sin ruido; jolgorio es alegría ruidosa y agitada. Se contrasta el estado del ambiente, sin valorar negativamente la alegría.","connection_type":"Contraste"},{"from_pdd":71,"to_pdd":189,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"Sosiego y recogimiento comparten tranquilidad y quietud; recogimiento añade concentración e intimidad reflexiva.","connection_type":"Directa"},{"from_pdd":72,"to_pdd":258,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Decir a bocajarro es hablar de golpe y sin rodeos; sincericidio añade que esa franqueza excesiva puede herir. No toda expresión directa es dañina.","connection_type":"Directa"},{"from_pdd":74,"to_pdd":190,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"Trasnochar y vigilia comparten permanecer despierto de noche; vigilia puede ser voluntaria por cuidado u oración y no exige acostarse tarde por ocio.","connection_type":"Directa"},{"from_pdd":74,"to_pdd":277,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"Trasnochar es permanecer despierto hasta tarde; desvelarse y desvelo, en la acepción de falta de sueño, comparten esa vigilia nocturna. Trasnochar puede ser voluntario y desvelarse puede ser involuntario; se excluye desvelar un secreto.","connection_type":"Directa"},{"from_pdd":75,"to_pdd":155,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"Ponerse las botas significa disfrutar mucho una oportunidad; gozar expresa disfrutar. Se reconoce el matiz intensivo y el uso frecuente de comida de la locución.","connection_type":"Directa"},{"from_pdd":75,"to_pdd":175,"relationship_type":"contraste_de_uso","strength":3,"explanation_es":"En su acepción alimentaria, ponerse las botas implica comer con abundancia; ayunar implica no comer durante un período.","connection_type":"Contraste"},{"from_pdd":78,"to_pdd":102,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Marear la perdiz alarga un asunto sin resolverlo; estirar el chicle lo prolonga en exceso para seguir aprovechándolo. Comparten dilación, con distinto fin.","connection_type":"Directa"},{"from_pdd":78,"to_pdd":107,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Marear la perdiz y irse por las ramas evitan llegar al punto principal; marear la perdiz destaca dar vueltas sin resolver y la otra locución apartarse del tema.","connection_type":"Directa"},{"from_pdd":79,"to_pdd":194,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Donde Jesucristo perdió la chancla y estar a años luz expresan distancia extrema; la primera localiza un lugar remoto y la segunda admite también distancia figurada.","connection_type":"Directa"},{"from_pdd":82,"to_pdd":121,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Oler a chamusquina y haber gato encerrado expresan sospecha de que algo no va bien; la segunda apunta particularmente a un engaño o secreto.","connection_type":"Directa"},{"from_pdd":82,"to_pdd":387,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Oler a chamusquina y olerse la tostada expresan sospechar un problema o intención oculta, sin limitarse a percibir un olor real.","connection_type":"Directa"},{"from_pdd":83,"to_pdd":380,"relationship_type":"sinonimia","strength":3,"explanation_es":"Ambos registros definen serendipia como hallazgo valioso o afortunado que ocurre de manera inesperada, sin buscarlo directamente.","connection_type":"Directa"},{"from_pdd":84,"to_pdd":236,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"El talento es capacidad personal cuyo descubrimiento aporta realización; pericia es habilidad desarrollada con experiencia. La distinción entre potencial y dominio adquirido es explícita.","connection_type":"Directa"},{"from_pdd":84,"to_pdd":358,"relationship_type":"acepcion_compartida","strength":2,"explanation_es":"Pericia es habilidad adquirida por experiencia; aptitud, dentro de Aptitud/Actitud, es capacidad para hacer algo. Se diferencia destreza entrenada de capacidad en general.","connection_type":"Directa"},{"from_pdd":85,"to_pdd":388,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Aleatorio depende del azar y no sigue orden previsible; un imponderable es una circunstancia que no se puede prever o calcular fácilmente. Coinciden en imprevisibilidad, no en que todo imprevisto sea azar puro.","connection_type":"Directa"},{"from_pdd":87,"to_pdd":294,"relationship_type":"contraste_de_uso","strength":3,"explanation_es":"Postergar deja una acción para después; darse vidilla pide acelerarla ahora. Son orientaciones temporales contrastantes ante una tarea.","connection_type":"Contraste"},{"from_pdd":87,"to_pdd":371,"relationship_type":"expresiones_cercanas","strength":3,"explanation_es":"Cagaprisas describe impaciencia habitual por hacerlo todo deprisa; darse vidilla pide acelerar. Comparten prisa, con valoración crítica frente a exhortación puntual.","connection_type":"Directa"},{"from_pdd":89,"to_pdd":168,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Arrepentirse reconoce con pesar lo hecho; a lo hecho pecho acepta sus consecuencias. Se distingue aceptación responsable de remordimiento, que no siempre van juntos.","connection_type":"Directa"},{"from_pdd":89,"to_pdd":241,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"Sea lo que sea acepta lo que ocurra sin condiciones; a lo hecho pecho acepta consecuencias de lo ya realizado. Se diferencia aceptación general de responsabilidad retrospectiva.","connection_type":"Directa"},{"from_pdd":90,"to_pdd":135,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Habitar es vivir habitualmente en un lugar; enraizarse añade establecer allí vínculos profundos. El enlace delimita residencia frente a arraigo.","connection_type":"Directa"},{"from_pdd":91,"to_pdd":129,"relationship_type":"acepcion_compartida","strength":3,"explanation_es":"La connotación es significado sugerido; implícito, en la sala implícito/explícito, designa lo que se sugiere sin expresarlo directamente. No toda información implícita es connotación léxica.","connection_type":"Directa"},{"from_pdd":91,"to_pdd":148,"relationship_type":"acepcion_compartida","strength":2,"explanation_es":"Figurado remite al sentido no literal y connotación a asociaciones añadidas; permiten distinguir dos ampliaciones de interpretación, sin confundir connotación y figuración ni el sentido figurativo artístico.","connection_type":"Directa"},{"from_pdd":92,"to_pdd":271,"relationship_type":"contraste_de_modo","strength":2,"explanation_es":"Irrumpir es entrar o aparecer repentina y fuertemente; asomar es aparecer de manera inicial y parcial. Se contrasta modo de aparición, no desplazamiento en general.","connection_type":"Contraste"},{"from_pdd":92,"to_pdd":282,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Asomar es comenzar a dejarse ver; atisbo puede ser la señal mínima de esa aparición y atisbar su percepción fugaz. Se contrasta aparecer parcialmente y percibir apenas.","connection_type":"Directa"},{"from_pdd":92,"to_pdd":398,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Asomar es empezar a verse y vislumbrar percibir algo vagamente; se vinculan aparición parcial y percepción parcial, sin convertirlos en verbos intercambiables.","connection_type":"Directa"},{"from_pdd":93,"to_pdd":277,"relationship_type":"equivalencia_nominal_verbal","strength":3,"explanation_es":"Desvelamiento es la acción de desvelar en su acepción de revelar lo oculto; se excluyen desvelarse y desvelo cuando significan perder el sueño.","connection_type":"Directa"},{"from_pdd":95,"to_pdd":244,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"Más te vale formula una advertencia de conveniencia; hazme caso pide atender el consejo. Comparten función de mover al interlocutor a seguir una indicación, con distinto tono y fuerza.","connection_type":"Directa"},{"from_pdd":96,"to_pdd":264,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Alzar la cabeza recupera el ánimo tras la adversidad; al mal tiempo buena cara mantiene una actitud positiva mientras dura. Se comparan recuperación y afrontamiento positivo.","connection_type":"Directa"},{"from_pdd":97,"to_pdd":231,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Ambas imágenes florales expresan renovación vital que continúa pese a obstáculos; el refrán afirma que la adversidad no consigue detener esa renovación.","connection_type":"Directa"},{"from_pdd":98,"to_pdd":220,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Ambas formulaciones atribuyen el cambio colectivo a acciones concretas de personas corrientes; una pide iniciativa personal y otra destaca su suma.","connection_type":"Directa"},{"from_pdd":98,"to_pdd":233,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Sé el cambio y donde hay un árbol que plantar plántalo tú invitan a comenzar la mejora por una acción propia, no a esperar que actúen otros.","connection_type":"Directa"},{"from_pdd":99,"to_pdd":212,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Las dos expresiones valoran una experiencia disfrutada aunque termine: nadie quita lo vivido y se agradece que haya ocurrido en vez de centrarse solo en la pérdida.","connection_type":"Directa"},{"from_pdd":100,"to_pdd":240,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Camino hecho al andar y vida bordada día a día presentan la propia vida como construcción progresiva mediante acciones y experiencias, con metáforas distintas.","connection_type":"Directa"},{"from_pdd":100,"to_pdd":323,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"La pregunta sobre dirigir la vida o ser arrastrado y el camino hecho al andar contrastan agencia personal y pasividad ante la trayectoria vital.","connection_type":"Directa"},{"from_pdd":101,"to_pdd":296,"relationship_type":"sinonimia","strength":3,"explanation_es":"Jolgorio y parranda expresan celebración animada y ruidosa; parranda suele nombrar la fiesta y jolgorio su ambiente.","connection_type":"Directa"},{"from_pdd":102,"to_pdd":348,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Estirar el chicle prolonga excesivamente un asunto; interminable describe el efecto de que parece no acabar. Se distingue acción dilatoria y duración percibida.","connection_type":"Directa"},{"from_pdd":104,"to_pdd":179,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Hacer malabares con obligaciones supone coordinar varias a la vez; abarcar varias tareas es incluirlas en el propio alcance. El primer uso añade dificultad de coordinación.","connection_type":"Directa"},{"from_pdd":105,"to_pdd":143,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Eso es el colmo protesta porque se supera lo tolerable; pasarse tres pueblos describe exceder esos límites. Se conectan valoración indignada y acción excesiva.","connection_type":"Directa"},{"from_pdd":106,"to_pdd":189,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Recogimiento es concentración tranquila y reflexiva; prestar atención es concentrar sentidos y mente. Comparten concentración, con un matiz interior y sereno en recogimiento.","connection_type":"Directa"},{"from_pdd":106,"to_pdd":244,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Prestar atención concentra los sentidos; hazme caso pide escuchar y atender, a menudo además seguir el consejo. No toda atención implica obediencia.","connection_type":"Directa"},{"from_pdd":108,"to_pdd":309,"relationship_type":"contraste_de_uso","strength":3,"explanation_es":"No cabe duda de que presenta una afirmación como segura; por qué estás tan seguro exige revisar la justificación de esa seguridad.","connection_type":"Contraste"},{"from_pdd":109,"to_pdd":162,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"Grandioso y prodigioso valoran algo como excepcional o admirable; prodigioso añade una impresión casi milagrosa que grandioso no exige.","connection_type":"Directa"},{"from_pdd":110,"to_pdd":128,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Rumiar preocupaciones es volver repetidamente al mismo pensamiento sin resolverlo, un bucle mental. Se excluye el sentido digestivo de rumiar.","connection_type":"Directa"},{"from_pdd":110,"to_pdd":152,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Bucle es una secuencia que se repite; estribillo es un segmento musical que reaparece. El estribillo ejemplifica repetición, sin ser necesariamente un bucle cerrado.","connection_type":"Directa"},{"from_pdd":113,"to_pdd":386,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Presagio es una señal interpretada como anuncio futuro; corazonada es un presentimiento sin pruebas claras. Se diferencia indicio exterior de intuición interior.","connection_type":"Directa"},{"from_pdd":116,"to_pdd":278,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Arrebato, en sentido emocional, es dejarse llevar por una emoción intensa; ser de mecha corta facilita arrebatos de enfado. Se excluye arrebatar como quitar por fuerza.","connection_type":"Directa"},{"from_pdd":117,"to_pdd":303,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Procurar es intentar con cuidado y esfuerzo; persistencia añade mantener ese intento a pesar de dificultades. Se distingue esfuerzo puntual de continuidad.","connection_type":"Directa"},{"from_pdd":118,"to_pdd":170,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"Más hermosa que un gorrino es un elogio humorístico de belleza; halagar es dedicar ese tipo de cumplido, sin extender la comparación a cualquier admiración.","connection_type":"Directa"},{"from_pdd":118,"to_pdd":208,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Halagar y echar flores coinciden en dedicar alabanzas o cumplidos; halagar puede añadir el propósito de agradar.","connection_type":"Directa"},{"from_pdd":120,"to_pdd":391,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Sostener mantiene algo firme; firmeza nombra esa estabilidad y, figuradamente, decisión ante dificultades. El enlace reconoce el paso de estabilidad física a estabilidad de postura.","connection_type":"Directa"},{"from_pdd":120,"to_pdd":393,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"Firmeza y determinación comparten mantenerse decidido ante obstáculos; determinación destaca la voluntad dirigida a un objetivo.","connection_type":"Directa"},{"from_pdd":121,"to_pdd":387,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Haber gato encerrado y olerse algo sugieren que existe una intención o engaño oculto que provoca desconfianza.","connection_type":"Directa"},{"from_pdd":122,"to_pdd":364,"relationship_type":"acepcion_compartida","strength":2,"explanation_es":"Compresión reduce volumen y por tanto ejemplifica disminuir; la sala de disminuir y ampliar contrapone escalas. Se excluye comprensión como entender y no se equipara toda disminución a compresión.","connection_type":"Directa"},{"from_pdd":124,"to_pdd":244,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"Obedecer cumple una indicación; hacer caso puede significar atenderla y seguirla. Se distingue de limitarse a escuchar sin cumplir.","connection_type":"Directa"},{"from_pdd":125,"to_pdd":262,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"La sala opone fortalecer y debilitar; el refrán afirma una posible fortaleza adquirida tras dificultades. Se enlaza exclusivamente el sentido de fortalecer, no una ley universal sobre el daño.","connection_type":"Directa"},{"from_pdd":125,"to_pdd":352,"relationship_type":"acepcion_compartida","strength":3,"explanation_es":"Endurecer puede hacer algo más resistente, sentido cercano a fortalecer; la misma sala contrapone debilitar, su dirección opuesta. No se confunde dureza física con toda fortaleza emocional.","connection_type":"Directa"},{"from_pdd":126,"to_pdd":157,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Saber a gloria y estar para chuparse los dedos valoran una comida como extremadamente deliciosa.","connection_type":"Directa"},{"from_pdd":127,"to_pdd":255,"relationship_type":"contraste_de_uso","strength":3,"explanation_es":"Saber más que un cuco atribuye astucia y conocimientos efectivos; sabelotodo critica la presunción de saberlo todo. Se contrasta capacidad atribuida con ostentación molesta.","connection_type":"Contraste"},{"from_pdd":129,"to_pdd":213,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"Lo implícito comunica sin decir directamente; el silencio que habla es una formulación de comunicación sin palabras. Se excluyen aquí los signos explícitos.","connection_type":"Directa"},{"from_pdd":132,"to_pdd":133,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"Cómplice y aliado colaboran con otra persona; cómplice suele implicar una acción compartida secreta o censurable que aliado no exige.","connection_type":"Directa"},{"from_pdd":134,"to_pdd":360,"relationship_type":"sinonimia_parcial","strength":2,"explanation_es":"Moldear da forma o influye en el desarrollo; adaptar modifica algo para ajustarlo a circunstancias. Se aproximan al cambiar una forma o conducta para adecuarla, sin equiparar adoptar como acoger.","connection_type":"Directa"},{"from_pdd":134,"to_pdd":399,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Moldear da forma o influye en el desarrollo; gestar forma o desarrolla una idea o proyecto. Coinciden en dar forma progresiva en usos figurados.","connection_type":"Directa"},{"from_pdd":137,"to_pdd":154,"relationship_type":"contraste_de_valoracion","strength":3,"explanation_es":"Costar un huevo destaca un precio excesivo mientras chollo destaca una compra muy ventajosa; se compara valoración del coste.","connection_type":"Contraste"},{"from_pdd":137,"to_pdd":270,"relationship_type":"contraste_de_valoracion","strength":3,"explanation_es":"Chollo es una oportunidad de precio ventajoso; costar un ojo de la cara valora un precio como extremadamente elevado. Se compara el juicio de coste, no un precio absoluto.","connection_type":"Contraste"},{"from_pdd":138,"to_pdd":305,"relationship_type":"sinonimia_parcial","strength":2,"explanation_es":"Ser bueno como el pan y ser majo pueden elogiar el trato agradable y amable; majo no implica necesariamente bondad moral y puede referirse a atractivo.","connection_type":"Directa"},{"from_pdd":138,"to_pdd":394,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Ser más bueno que el pan atribuye bondad extraordinaria; benevolencia nombra la actitud comprensiva y de buena voluntad que expresa esa bondad.","connection_type":"Directa"},{"from_pdd":139,"to_pdd":140,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"A ciegas y a tientas coinciden en actuar sin visión; a tientas añade buscar por el tacto, y a ciegas permite desconocimiento figurado.","connection_type":"Directa"},{"from_pdd":139,"to_pdd":153,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Actuar a ciegas sin saber qué sucederá se aproxima a la desorientación expresada por estar perdido como un pulpo en un garaje; no son equivalentes en incapacidad visual literal.","connection_type":"Directa"},{"from_pdd":144,"to_pdd":158,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Meterse en berenjenales implica involucrarse en asuntos complicados; liarse parda describe un gran lío o problema provocado. Se distinguen implicación y desencadenamiento.","connection_type":"Directa"},{"from_pdd":149,"to_pdd":258,"relationship_type":"contraste_de_uso","strength":2,"explanation_es":"Sincericidio comunica con franqueza excesiva que puede herir; sutileza permite comunicar matices con delicadeza. Se contrasta modo directo y modo delicado, no verdad y mentira.","connection_type":"Contraste"},{"from_pdd":154,"to_pdd":270,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Costar un huevo y costar un ojo de la cara son expresiones intensivas de precio muy alto; se excluye aquí el uso de costar un huevo como esfuerzo no monetario.","connection_type":"Directa"},{"from_pdd":156,"to_pdd":252,"relationship_type":"antonimia_de_funcion","strength":3,"explanation_es":"La alegría de la huerta anima a los demás; un aguafiestas estropea su diversión o entusiasmo. Son funciones sociales contrastantes, no juicios totales sobre una persona.","connection_type":"Contraste"},{"from_pdd":159,"to_pdd":246,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"Echar un cable es ayudar; la cita define el amor como ayudar al otro a ser auténtico. Se conecta la acción concreta de ayudar con esa definición de apoyo personal.","connection_type":"Directa"},{"from_pdd":161,"to_pdd":265,"relationship_type":"contraste_de_uso","strength":3,"explanation_es":"A quien madruga aconseja actuar temprano; no por mucho madrugar advierte que empezar antes no acelera todos los procesos. Son recomendaciones contrastantes, no reglas lógicas incompatibles en todo contexto.","connection_type":"Contraste"},{"from_pdd":163,"to_pdd":328,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Aunar es unir fuerzas para un fin común; tender puentes para acuerdos propone unir voluntades frente a separarlas.","connection_type":"Directa"},{"from_pdd":167,"to_pdd":320,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Carecer de recursos necesarios puede constituir precariedad; precario añade inseguridad o inestabilidad. Se limita a la acepción de recursos insuficientes.","connection_type":"Directa"},{"from_pdd":172,"to_pdd":320,"relationship_type":"contraste_de_significado","strength":3,"explanation_es":"Rebosar expresa abundancia que supera la capacidad; carecer expresa ausencia o falta de lo necesario. En uso figurado, rebosar de alegría contrasta con carecer de alegría: sobra frente a falta.","connection_type":"Contraste"},{"from_pdd":176,"to_pdd":250,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"Encontrarse sin buscarse y el mundo es un pañuelo presentan encuentros inesperados entre personas. La primera añade una interpretación poética de afinidad o destino.","connection_type":"Directa"},{"from_pdd":177,"to_pdd":253,"relationship_type":"contraste_de_actitud","strength":3,"explanation_es":"Malgastar desperdicia recursos; lonchafinista describe ahorro extremo. Se contrastan dos formas de gestionar gasto, sin presentar la tacañería como virtud obligatoria.","connection_type":"Contraste"},{"from_pdd":178,"to_pdd":179,"relationship_type":"contraste_morfosemantico","strength":3,"explanation_es":"Inabarcable niega la posibilidad de abarcar por exceso de amplitud; abarcar expresa incluir o alcanzar el conjunto. Comparten la misma operación y su límite.","connection_type":"Contraste"},{"from_pdd":182,"to_pdd":303,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"El que la sigue la consigue recomienda continuar pese a dificultades, la misma perseverancia que define persistencia, sin garantizar siempre el éxito real.","connection_type":"Directa"},{"from_pdd":183,"to_pdd":364,"relationship_type":"acepcion_compartida","strength":2,"explanation_es":"Aplastar puede reducir el volumen por presión; compresión nombra reducir volumen. Se excluye comprensión como entender y los usos figurados de aplastar a un rival.","connection_type":"Directa"},{"from_pdd":185,"to_pdd":210,"relationship_type":"contraste_de_valoracion","strength":3,"explanation_es":"La flor y nata sitúa a alguien en una élite selecta; pelagatos lo rebaja despectivamente a insignificancia social. Se comparan valoraciones de estatus, sin legitimarlas.","connection_type":"Contraste"},{"from_pdd":186,"to_pdd":399,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Concepción y gestación pueden referirse al origen y desarrollo de una vida o idea; son fases relacionadas, no sinónimos en toda su duración.","connection_type":"Directa"},{"from_pdd":190,"to_pdd":277,"relationship_type":"acepcion_compartida","strength":2,"explanation_es":"Vigilia y desvelarse comparten permanecer sin dormir; vigilia puede ser una decisión de cuidado y desvelarse un efecto de preocupación. No se usa desvelar como revelar.","connection_type":"Directa"},{"from_pdd":191,"to_pdd":228,"relationship_type":"contraste_de_uso","strength":2,"explanation_es":"Agua pasada no mueve molino resta eficacia a lo ya ocurrido; borrón y cuenta nueva propone dejar errores pasados para empezar de nuevo. Comparten dejar atrás el pasado con distinta función discursiva.","connection_type":"Contraste"},{"from_pdd":191,"to_pdd":263,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"Borrón y cuenta nueva propone recomenzar tras errores; cuando una puerta se cierra otra se abre presenta el final como ocasión para otro comienzo.","connection_type":"Directa"},{"from_pdd":192,"to_pdd":206,"relationship_type":"antonimia_de_etapa","strength":3,"explanation_es":"Entrado en años indica edad avanzada; estar en la flor de la vida destaca juventud y plenitud. Se contrastan etapas, sin equiparar edad avanzada con falta de salud o valor.","connection_type":"Contraste"},{"from_pdd":197,"to_pdd":319,"relationship_type":"antonimia","strength":3,"explanation_es":"El año de la pera remite a un pasado muy remoto; reciente a lo ocurrido hace poco. Contrastan directamente distancia temporal.","connection_type":"Contraste"},{"from_pdd":198,"to_pdd":226,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"Hacer el agosto es aprovechar una ocasión para ganar mucho; a río revuelto ganancia de pescadores limita esa ventaja a una situación de confusión.","connection_type":"Directa"},{"from_pdd":198,"to_pdd":336,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Ambos registros de hacer el agosto expresan conseguir grandes beneficios aprovechando una situación especialmente favorable.","connection_type":"Directa"},{"from_pdd":199,"to_pdd":200,"relationship_type":"relacion_especificacion","strength":3,"explanation_es":"Bicentenario es una conmemoración de doscientos años que puede ser una efeméride; efeméride es cualquier fecha de recuerdo de un hecho importante.","connection_type":"Directa"},{"from_pdd":207,"to_pdd":261,"relationship_type":"contraste_de_uso","strength":2,"explanation_es":"No todo es color de rosa advierte del lado difícil de una realidad; no hay mal que por bien no venga invita a encontrar un efecto favorable dentro de esa dificultad.","connection_type":"Contraste"},{"from_pdd":209,"to_pdd":348,"relationship_type":"antonimia","strength":3,"explanation_es":"Como flor de un día indica duración breve; interminable una duración que parece no acabar. Se contrasta extensión temporal, no flores literales.","connection_type":"Contraste"},{"from_pdd":217,"to_pdd":247,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Ambas citas presentan la lectura como felicidad: una imagina la biblioteca como paraíso y la otra el leer como placer íntimo. Comparten valoración explícita de leer, no solo libros como tema.","connection_type":"Directa"},{"from_pdd":220,"to_pdd":233,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Las pequeñas acciones que cambian el mundo y plantar uno mismo el árbol invitan a actuar personalmente en mejoras concretas y acumulativas.","connection_type":"Directa"},{"from_pdd":226,"to_pdd":336,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"Ambas locuciones pueden expresar obtener beneficios aprovechando una ocasión; a río revuelto añade que la ocasión nace del desorden o confusión.","connection_type":"Directa"},{"from_pdd":230,"to_pdd":265,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"Ambos refranes aconsejan actuar con diligencia para no perder ventajas; uno advierte sobre descuido y el otro recomienda iniciativa temprana.","connection_type":"Directa"},{"from_pdd":231,"to_pdd":262,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"La primavera que no pueden detener y la fortaleza tras superar dificultades expresan resistencia ante adversidad. La primera subraya renovación colectiva y la segunda fortaleza individual.","connection_type":"Directa"},{"from_pdd":241,"to_pdd":243,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Sea lo que sea y de todos modos mantienen una disposición independientemente de las circunstancias; la primera expresa aceptación y la segunda continuidad argumentativa.","connection_type":"Directa"},{"from_pdd":246,"to_pdd":307,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"La cita que define amar como ayudar al otro y el cuidado como amor coinciden en entender el afecto como apoyo activo a necesidades y autenticidad ajenas.","connection_type":"Directa"},{"from_pdd":248,"to_pdd":400,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"La cita describe una transformación profunda de la manera de vivir por el cariño; transmutir, según la definición del registro, nombra un cambio profundo de naturaleza. El enlace se limita a ese cambio interior, no al amor como tema ni a la alquimia literal.","connection_type":"Directa"},{"from_pdd":254,"to_pdd":321,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Correcaminos caracteriza desplazamiento muy rápido; apurarse puede ser darse prisa. Se limita al uso de rapidez, no a sentirse angustiado.","connection_type":"Directa"},{"from_pdd":259,"to_pdd":295,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Inmortal en la memoria significa permanecer recordado; trascender puede ser alcanzar importancia duradera más allá de lo inmediato. Se excluye inmortalidad biológica literal.","connection_type":"Directa"},{"from_pdd":259,"to_pdd":397,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"La acepción figurada de inmortal coincide con dejar una huella duradera, parte de la definición de trascender en este registro.","connection_type":"Directa"},{"from_pdd":261,"to_pdd":263,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"De un mal puede surgir un bien y una puerta cerrada puede abrir otra oportunidad: ambas expresiones reinterpretan un contratiempo como posibilidad favorable.","connection_type":"Directa"},{"from_pdd":262,"to_pdd":264,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Al mal tiempo buena cara recomienda actitud positiva ante la adversidad; el otro refrán subraya fortaleza adquirida al superarla. Se distinguen actitud y resultado posible.","connection_type":"Directa"},{"from_pdd":272,"to_pdd":399,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Brotar señala el inicio visible de un crecimiento; gestarse es ir formándose gradualmente antes o durante su aparición. Se delimitan fases de desarrollo, no toda actividad natural.","connection_type":"Directa"},{"from_pdd":279,"to_pdd":365,"relationship_type":"acepcion_compartida","strength":3,"explanation_es":"Entrañable despierta afecto y cercanía; afecto, dentro de Afecto/Efecto, nombra ese cariño. No se usa efecto como consecuencia.","connection_type":"Directa"},{"from_pdd":282,"to_pdd":398,"relationship_type":"sinonimia_parcial","strength":3,"explanation_es":"Atisbar y vislumbrar comparten percibir apenas o fugazmente; atisbo y vislumbre nombran indicios tenues. No se equipara toda observación detenida.","connection_type":"Directa"},{"from_pdd":283,"to_pdd":395,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Plantear una cuestión implica formularla para considerarla; verbalizar convierte una idea en palabras. Se limita a la formulación verbal de preguntas o problemas.","connection_type":"Directa"},{"from_pdd":285,"to_pdd":396,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Sensatez es decidir con buen juicio; discernir distingue diferencias para comprender y juzgar mejor. Se vinculan juicio prudente y capacidad discriminadora.","connection_type":"Directa"},{"from_pdd":288,"to_pdd":289,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Esencia es lo fundamental de algo; quintaesencia destaca su manifestación más pura o representativa, con intensificación y selección de lo esencial.","connection_type":"Directa"},{"from_pdd":288,"to_pdd":357,"relationship_type":"acepcion_compartida","strength":2,"explanation_es":"La esencia incluye los rasgos fundamentales; cualidad es una característica. Se conecta con cualidad y se distingue de calidad como excelencia.","connection_type":"Directa"},{"from_pdd":289,"to_pdd":357,"relationship_type":"acepcion_compartida","strength":2,"explanation_es":"Quintaesencia selecciona lo más puro o perfecto; calidad nombra grado de excelencia. Se conecta con calidad y no con cualquier cualidad descriptiva.","connection_type":"Directa"},{"from_pdd":295,"to_pdd":397,"relationship_type":"sinonimia","strength":3,"explanation_es":"Los dos registros de trascender comparten ir más allá de límites e importancia duradera; el segundo explicita superar lo inmediato y dejar huella.","connection_type":"Directa"},{"from_pdd":298,"to_pdd":299,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Llevarse a las mil maravillas y hacer buenas migas expresan entenderse muy bien; hacer buenas migas suele destacar el inicio de esa afinidad.","connection_type":"Directa"},{"from_pdd":305,"to_pdd":394,"relationship_type":"sinonimia_parcial","strength":2,"explanation_es":"Majo en su sentido de amable y simpático se aproxima al trato de buena voluntad de benevolencia; se excluye majo como atractivo físico.","connection_type":"Directa"},{"from_pdd":306,"to_pdd":395,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"Hablar incluso sin respuesta mantiene la necesidad de expresar; verbalizar es expresar pensamientos o emociones con palabras, haya o no contestación.","connection_type":"Directa"},{"from_pdd":311,"to_pdd":333,"relationship_type":"expresiones_equivalentes","strength":2,"explanation_es":"La cita sitúa el estilo en la sensibilidad personal, una fuente de expresión propia vinculada a originalidad; no afirma que cualquier estilo sea novedoso.","connection_type":"Directa"},{"from_pdd":311,"to_pdd":335,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Originalidad es creación propia; la cita sobre aprendizaje técnico e iniciación a la personalidad describe cómo se desarrolla un estilo artístico propio, no arte como etiqueta general.","connection_type":"Directa"},{"from_pdd":312,"to_pdd":313,"relationship_type":"relacion_especificacion","strength":3,"explanation_es":"Trencadís es una técnica de mosaico de fragmentos cerámicos irregulares; se conecta con mosaico dentro de la sala Vidriera/Mosaico, no con vidrio por coincidencia visual.","connection_type":"Directa"},{"from_pdd":317,"to_pdd":365,"relationship_type":"acepcion_compartida","strength":2,"explanation_es":"De amor remite al cariño; afecto, dentro del par Afecto/Efecto, también nombra cariño. Se excluye efecto como consecuencia.","connection_type":"Directa"},{"from_pdd":321,"to_pdd":371,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Apurarse puede significar darse prisa; cagaprisas caracteriza a quien siempre quiere actuar deprisa y con impaciencia. Se distingue acción puntual y hábito criticado.","connection_type":"Directa"},{"from_pdd":326,"to_pdd":327,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"La paz que se construye y la paz como proceso sin fin subrayan mantenimiento activo de convivencia; una destaca producción y otra continuidad.","connection_type":"Directa"},{"from_pdd":326,"to_pdd":330,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"La paz se hace y la paz es una ardua tarea coinciden en que la paz exige acción y esfuerzo, no mera espera o deseo.","connection_type":"Directa"},{"from_pdd":327,"to_pdd":330,"relationship_type":"expresiones_equivalentes","strength":3,"explanation_es":"Ambas citas definen la paz como trabajo persistente y no un estado que se obtiene de una vez para siempre.","connection_type":"Directa"},{"from_pdd":333,"to_pdd":335,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Ambas citas describen el estilo propio del artista: sensibilidad personal en una y aprendizaje técnico que desarrolla personalidad en la otra. La relación específica es autoría y estilo, no mera pintura.","connection_type":"Directa"},{"from_pdd":360,"to_pdd":400,"relationship_type":"contraste_de_transformacion","strength":2,"explanation_es":"Adaptar ajusta algo a nuevas circunstancias manteniendo parte de su naturaleza; transmutir, según el registro, implica cambio profundo a otra naturaleza. Se contrasta ajuste y transformación, no adoptar como aceptar.","connection_type":"Contraste"},{"from_pdd":386,"to_pdd":389,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Tener una corazonada y tener olfato para algo son formas de intuición sin prueba explícita; olfato suele destacar habilidad para detectar oportunidades o peligros.","connection_type":"Directa"},{"from_pdd":387,"to_pdd":389,"relationship_type":"significados_cercanos","strength":3,"explanation_es":"Olerse algo sospecha una intención o problema oculto; tener olfato para algo es habilidad intuitiva para detectarlos. Se distingue episodio de sospecha y capacidad habitual.","connection_type":"Directa"},{"from_pdd":392,"to_pdd":396,"relationship_type":"significados_cercanos","strength":2,"explanation_es":"Discurrir, en su acepción de pensar, desarrolla un razonamiento; discernir distingue diferencias para comprender y juzgar. Se comparan dos operaciones de pensamiento, sin incluir discurrir como fluir el agua.","connection_type":"Directa"}]$pdd_data$::jsonb) AS x(from_pdd bigint,to_pdd bigint,relationship_type text,strength integer,explanation_es text,connection_type text);
