DO $check$
BEGIN
 IF (SELECT count(*) FROM _pdd_scope)<>396 OR (SELECT count(*) FROM _pdd_proposal)<>215 OR (SELECT count(*) FROM _pdd_expected)<>1101 THEN
   RAISE EXCEPTION 'Embedded source counts do not match reviewed proposal';
 END IF;
 -- Validate degree at BOTH endpoints before touching any persistent data.
 IF EXISTS (SELECT pdd FROM (SELECT from_pdd AS pdd FROM _pdd_proposal UNION ALL SELECT to_pdd FROM _pdd_proposal) e GROUP BY pdd HAVING count(*)>3) THEN
   RAISE EXCEPTION 'Proposed endpoint exceeds three semantic connections';
 END IF;
 IF (WITH endpoints AS (SELECT from_pdd AS pdd FROM _pdd_proposal UNION ALL SELECT to_pdd FROM _pdd_proposal),
   degrees AS (SELECT s.pdd,count(e.pdd) AS degree FROM _pdd_scope s LEFT JOIN endpoints e USING(pdd) GROUP BY s.pdd),
   histogram AS (SELECT degree,count(*) AS rooms FROM degrees GROUP BY degree)
   SELECT jsonb_object_agg(degree::text,rooms) FROM histogram) IS DISTINCT FROM '{"0":138,"1":115,"2":114,"3":29}'::jsonb THEN
   RAISE EXCEPTION 'Embedded proposal degree histogram differs from reviewed source';
 END IF;
 IF EXISTS (SELECT 1 FROM _pdd_proposal p WHERE NOT EXISTS(SELECT 1 FROM _pdd_scope s WHERE s.pdd=p.from_pdd) OR NOT EXISTS(SELECT 1 FROM _pdd_scope s WHERE s.pdd=p.to_pdd)) THEN
   RAISE EXCEPTION 'Invalid proposal endpoint';
 END IF;
 IF EXISTS (SELECT s.pdd FROM _pdd_scope s LEFT JOIN public.rooms r ON r.pdd=s.pdd GROUP BY s.pdd HAVING count(r.id)<>1) OR
    EXISTS (SELECT 1 FROM _pdd_scope s JOIN public.rooms r ON r.pdd=s.pdd WHERE r.id IS DISTINCT FROM s.room_id OR r.word IS DISTINCT FROM s.word OR r.published IS DISTINCT FROM s.published) THEN
   RAISE EXCEPTION 'Vocabulary identity/word/publication drift; no room is changed';
 END IF;
 IF EXISTS (SELECT 1 FROM _pdd_expected e LEFT JOIN public.room_connections c ON c.id=e.id
    WHERE c.id IS NULL OR to_jsonb(c) IS DISTINCT FROM to_jsonb(jsonb_populate_record(NULL::public.room_connections,e.row_data))) THEN
   RAISE EXCEPTION 'Existing row missing or changed since read-only export; refresh/review backup rather than overwrite';
 END IF;
 IF EXISTS (SELECT 1 FROM _pdd_expected e WHERE NOT EXISTS(SELECT 1 FROM _pdd_scope s WHERE s.pdd=(e.row_data->>'from_pdd')::bigint) OR NOT EXISTS(SELECT 1 FROM _pdd_scope s WHERE s.pdd=(e.row_data->>'to_pdd')::bigint)) THEN
   RAISE EXCEPTION 'Backup contains an out-of-scope connection';
 END IF;
 IF EXISTS (SELECT 1 FROM public.room_connections c WHERE (c.from_pdd IN(SELECT pdd FROM _pdd_scope) OR c.to_pdd IN(SELECT pdd FROM _pdd_scope)) AND NOT EXISTS(SELECT 1 FROM _pdd_expected e WHERE e.id=c.id)) THEN
   RAISE EXCEPTION 'Additional/hidden incident connection found; scope requires review, even if row is disabled';
 END IF;
 IF EXISTS (SELECT least(c.from_pdd,c.to_pdd),greatest(c.from_pdd,c.to_pdd) FROM public.room_connections c JOIN _pdd_expected e ON e.id=c.id
   GROUP BY least(c.from_pdd,c.to_pdd),greatest(c.from_pdd,c.to_pdd) HAVING count(*)>1) THEN
   RAISE EXCEPTION 'Duplicate/reverse existing pair requires review';
 END IF;
END $check$;

-- A named, private backup namespace also makes an accidental rerun fail before any public-table write.
CREATE SCHEMA pdd_semantic_215_backup_20261031;
REVOKE ALL ON SCHEMA pdd_semantic_215_backup_20261031 FROM PUBLIC;
CREATE TABLE pdd_semantic_215_backup_20261031.run_state (singleton boolean PRIMARY KEY CHECK(singleton),state text NOT NULL CHECK(state IN('applied','rolled_back')),
 proposal_sha256 text NOT NULL,schema_md5 text NOT NULL,executed_at timestamptz NOT NULL DEFAULT now(),rolled_back_at timestamptz);
CREATE TABLE pdd_semantic_215_backup_20261031.before_rows (id bigint PRIMARY KEY,row_data jsonb NOT NULL);
CREATE TABLE pdd_semantic_215_backup_20261031.after_rows (id bigint PRIMARY KEY,row_data jsonb NOT NULL);
CREATE TABLE pdd_semantic_215_backup_20261031.new_ids (id bigint PRIMARY KEY);
CREATE TABLE pdd_semantic_215_backup_20261031.scope AS TABLE _pdd_scope;
CREATE TABLE pdd_semantic_215_backup_20261031.proposal AS TABLE _pdd_proposal;
REVOKE ALL ON ALL TABLES IN SCHEMA pdd_semantic_215_backup_20261031 FROM PUBLIC;
DO $private$ DECLARE role_name text; BEGIN
 FOR role_name IN SELECT rolname FROM pg_roles WHERE rolname IN('anon','authenticated') LOOP
  EXECUTE format('REVOKE ALL ON SCHEMA pdd_semantic_215_backup_20261031 FROM %I',role_name);
  EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA pdd_semantic_215_backup_20261031 FROM %I',role_name);
 END LOOP;
END $private$;
INSERT INTO pdd_semantic_215_backup_20261031.before_rows SELECT c.id,to_jsonb(c) FROM public.room_connections c JOIN _pdd_expected e ON e.id=c.id;
CREATE TEMP TABLE _pdd_unrelated ON COMMIT DROP AS SELECT c.id,to_jsonb(c) AS row_data FROM public.room_connections c WHERE NOT EXISTS(SELECT 1 FROM _pdd_expected e WHERE e.id=c.id);
CREATE TEMP TABLE _pdd_rooms_before ON COMMIT DROP AS SELECT id,to_jsonb(r) AS row_data FROM public.rooms r;

-- Soft replacement: obsolete rows remain for history/FKs, but enabled=true queries ignore them.
UPDATE public.room_connections c SET enabled=false
 WHERE c.id IN(SELECT id FROM pdd_semantic_215_backup_20261031.before_rows)
 AND NOT EXISTS(SELECT 1 FROM _pdd_proposal p WHERE p.from_pdd=least(c.from_pdd,c.to_pdd) AND p.to_pdd=greatest(c.from_pdd,c.to_pdd));
-- Retain existing IDs AND endpoint orientation for pairs already present.
UPDATE public.room_connections c SET enabled=true,featured=false,strength=p.strength,reason=p.explanation_es,
 relationship=p.relationship_type,connection_type=p.connection_type
 FROM _pdd_proposal p WHERE c.id IN(SELECT id FROM pdd_semantic_215_backup_20261031.before_rows)
 AND p.from_pdd=least(c.from_pdd,c.to_pdd) AND p.to_pdd=greatest(c.from_pdd,c.to_pdd);
WITH inserted AS (
 INSERT INTO public.room_connections(from_pdd,to_pdd,enabled,featured,strength,reason,relationship,connection_type)
 SELECT p.from_pdd,p.to_pdd,true,false,p.strength,p.explanation_es,p.relationship_type,p.connection_type FROM _pdd_proposal p
 WHERE NOT EXISTS(SELECT 1 FROM public.room_connections c WHERE least(c.from_pdd,c.to_pdd)=p.from_pdd AND greatest(c.from_pdd,c.to_pdd)=p.to_pdd)
 RETURNING id
) INSERT INTO pdd_semantic_215_backup_20261031.new_ids SELECT id FROM inserted;
SET CONSTRAINTS ALL IMMEDIATE;
DO $verify$
DECLARE actual jsonb;
BEGIN
 IF (SELECT count(*) FROM public.room_connections c WHERE c.enabled=true AND (c.from_pdd IN(SELECT pdd FROM _pdd_scope) OR c.to_pdd IN(SELECT pdd FROM _pdd_scope)))<>215 THEN
   RAISE EXCEPTION 'Expected exactly 215 enabled PDD semantic connections';
 END IF;
 IF (SELECT count(*) FROM public.room_connections c JOIN _pdd_proposal p ON least(c.from_pdd,c.to_pdd)=p.from_pdd AND greatest(c.from_pdd,c.to_pdd)=p.to_pdd
     WHERE c.enabled=true AND c.reason IS NOT DISTINCT FROM p.explanation_es AND c.relationship IS NOT DISTINCT FROM p.relationship_type
       AND c.connection_type IS NOT DISTINCT FROM p.connection_type AND c.strength=p.strength AND c.featured=false)<>215 THEN
   RAISE EXCEPTION 'Proposal pairs/types/strengths/Spanish explanations differ from source';
 END IF;
 WITH endpoints AS (SELECT c.from_pdd AS pdd FROM public.room_connections c WHERE c.enabled=true AND (c.from_pdd IN(SELECT pdd FROM _pdd_scope) OR c.to_pdd IN(SELECT pdd FROM _pdd_scope))
 UNION ALL SELECT c.to_pdd FROM public.room_connections c WHERE c.enabled=true AND (c.from_pdd IN(SELECT pdd FROM _pdd_scope) OR c.to_pdd IN(SELECT pdd FROM _pdd_scope))),
 degrees AS (SELECT s.pdd,count(e.pdd) AS degree FROM _pdd_scope s LEFT JOIN endpoints e USING(pdd) GROUP BY s.pdd),
 histogram AS (SELECT degree,count(*) AS rooms FROM degrees GROUP BY degree)
 SELECT jsonb_object_agg(degree::text,rooms) INTO actual FROM histogram;
 IF actual IS DISTINCT FROM '{"0":138,"1":115,"2":114,"3":29}'::jsonb THEN RAISE EXCEPTION 'Unexpected endpoint degree histogram: %',actual; END IF;
 IF EXISTS (SELECT least(c.from_pdd,c.to_pdd),greatest(c.from_pdd,c.to_pdd) FROM public.room_connections c
